        int n = Integer.parseInt(sc.nextLine().trim());
        int same = 0;
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            if (parts[1].equals(parts[2])) {
                same++;
            } else {
                System.out.println("DIFF " + parts[0] + " " + parts[1] + " " + parts[2]);
            }
        }
        System.out.println("安定 " + same + "/" + n);
        System.out.println("判定 " + (same == n ? "移植できる" : "既定値に依存"));
    }
}

