import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), jdk = 0;
        for (int i = 0; i < n; i++) {
            boolean needsCompile = sc.next().equals("yes");
            // 仕様はAPIの範囲だけで決まる。コンパイルするかどうかとは連動しない
            String edition = switch (sc.next()) {
                case "web" -> "EE";
                case "device" -> "ME";
                default -> "SE";
            };
            if (needsCompile) {
                jdk++;
            }
            System.out.println((needsCompile ? "JDK" : "JVM") + " " + edition);
        }
        System.out.println("jdk=" + jdk);
    }
}

