        int required = majorVersion - 44;
        int runnable = 0;
        for (int i = 0; i < n; i++) {
            int release = Integer.parseInt(parts[i]);
            boolean ok = release >= required;
            if (ok) {
                runnable++;
            }
            System.out.println(release + " " + (ok ? "RUN" : "UnsupportedClassVersionError"));
        }
        System.out.println("必要なリリース " + required);
        System.out.println("動く " + runnable + "/" + n);
    }
}

